from PIL import Image
im=Image.open('/app/chess_board.png').convert('RGB')
sq=80
light=(240,217,181)
dark=(181,136,99)
def bg(c):
    return c==light or c==dark

def render(row,col,scale=2):
    x0=col*sq; y0=row*sq
    out=[]
    for yy in range(y0+6,y0+sq-2,scale):
        line=''
        for xx in range(x0+2,x0+sq-2,scale):
            cnt=0;tot=0;blk=0;wht=0
            for dy in range(scale):
                for dx in range(scale):
                    c=im.getpixel((xx+dx,yy+dy))
                    tot+=1
                    if not bg(c):
                        cnt+=1
                        r,g,b=c
                        if r<100:blk+=1
                        elif r>200:wht+=1
            if cnt>scale*scale*0.25:
                line += 'B' if blk>wht else 'W'
            else:
                line += ' '
        out.append(line)
    return out

for s in ['a8','c8','d8','f8','c6','d5','f5','g5','e5','c3','e2','a1','c1','e1','h1']:
    print("===",s)
    for line in render(8-int(s[1]),ord(s[0])-ord('a')):
        print(line)
